/** The language IDs of glob patterns, as expressions that match a lowercase repository path, the longest pattern first. */
export const languagePatterns: readonly (readonly [RegExp, string])[] = [
   [/^(?:.*\/)?user\/profiles\/[^/]*\/snippets\/[^/]*\.json$/, 'snippets'], // **/User/profiles/*/snippets/*.json
   [/^(?:.*\/)?\.claude\/rules\/(?:.*\/)?[^/]*\.md$/, 'instructions'], // **/.claude/rules/**/*.md
   [/^(?:.*\/)?\.github\/hooks\/[^/]*\.json$/, 'jsonc'], // **/.github/hooks/*.json
   [/^(?:.*\/)?user\/snippets\/[^/]*\.json$/, 'snippets'], // **/User/snippets/*.json
   [/^(?:.*\/)?\.github\/agents\/[^/]*\.md$/, 'chatagent'], // **/.github/agents/*.md
   [/^(?:.*\/)?\.claude\/agents\/[^/]*\.md$/, 'chatagent'], // **/.claude/agents/*.md
   [/^(?:.*\/)?\.config\/git\/config$/, 'properties'], // **/.config/git/config
   [/(?:^|\/)[^/]*docker[^/]*compose[^/]*\.yaml$/, 'dockercompose'], // *docker*compose*.yaml
   [/^(?:.*\/)?rebase-merge\/done$/, 'git-rebase'], // **/rebase-merge/done
   [/(?:^|\/)[^/]*docker[^/]*compose[^/]*\.yml$/, 'dockercompose'], // *docker*compose*.yml
   [/^(?:.*\/)?\.cursor\/(?:.*\/)?[^/]*\.mdc$/, 'markdown'], // **/.cursor/**/*.mdc
   [/^(?:.*\/)?snippets[^/]*\.json$/, 'snippets'], // **/snippets*.json
   [/(?:^|\/)containerfile\.[^/]*$/, 'dockerfile'], // Containerfile.*
   [/(?:^|\/)tsconfig\.[^/]*\.json$/, 'jsonc'], // tsconfig.*.json
   [/(?:^|\/)jsconfig\.[^/]*\.json$/, 'jsonc'], // jsconfig.*.json
   [/(?:^|\/)tsconfig-[^/]*\.json$/, 'jsonc'], // tsconfig-*.json
   [/(?:^|\/)jsconfig-[^/]*\.json$/, 'jsonc'], // jsconfig-*.json
   [/^(?:.*\/)?\.git\/config$/, 'properties'], // **/.git/config
   [/(?:^|\/)compose\.[^/]*\.yaml$/, 'dockercompose'], // compose.*.yaml
   [/(?:^|\/)compose\.[^/]*\.yml$/, 'dockercompose'], // compose.*.yml
   [/(?:^|\/)dockerfile\.[^/]*$/, 'dockerfile'], // Dockerfile.*
   [/(?:^|\/)jenkinsfile[^/]*$/, 'groovy'], // Jenkinsfile*
   [/(?:^|\/)compose\.yaml$/, 'dockercompose'], // compose.yaml
   [/(?:^|\/)compose\.yml$/, 'dockercompose'], // compose.yml
   [/(?:^|\/)\.env\.[^/]*$/, 'dotenv'], // .env.*
];
